(()=>{'use strict';const D=window.RUNDOWNS,M=window.RundownModel,E=M.escape,$=id=>document.getElementById(id),KEY='contest-command-rundowns-v2';let state={schema:2,plan:'contest-command-rundowns',records:{},capacity:null},editing=null,search='',status='open',windowFilter='all';
try{const raw=localStorage.getItem(KEY);if(raw)state=M.validate(JSON.parse(raw),D.tasks);}catch{$('storage').hidden=false;$('storage').textContent='Stored plan could not be read. Older dashboard records remain separate; import a valid backup.';}
const project=id=>D.projects.find(p=>p.id===id),stat=t=>state.records[t.id]?.status||'todo',done=ts=>ts.filter(t=>stat(t)==='done').length,hours=ts=>Math.round(ts.reduce((s,t)=>s+t.hours,0)*100)/100;
const aliases={hack:'meta',mega:'mega',lt:'lt'};function route(){const r=location.hash.slice(1)||'overview';return aliases[r]||r;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('storage').hidden=true;}catch{$('storage').hidden=false;$('storage').textContent='Storage failed. Export progress before closing this page.';}}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function dateLabel(d){return new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric',timeZone:'America/Chicago'}).format(new Date(d+'T12:00:00Z'));}
function task(t){const r=state.records[t.id],missing=t.depends.filter(id=>stat(D.tasks.find(x=>x.id===id))!=='done');return `<details class="task" id="task-${t.id}"><summary><span class="badge">${E(t.id)}</span><span class="title"><b>${E(t.title)}</b><br><span class="meta">${E(project(t.project).name)} · ${t.hours}h estimate · ${E(t.phase)}</span></span><span class="badge ${stat(t)}">${E(stat(t))}</span></summary><div class="body"><p class="meta">${E(t.owner)} · Proposed ${E(t.date)}</p><ol>${t.steps.map(s=>`<li>${E(s)}</li>`).join('')}</ol><div class="criteria"><b>Done when</b><p>${E(t.done)}</p></div>${t.condition?`<p class="notice warning">${E(t.condition)}</p>`:''}<p class="meta">Do first: ${t.depends.length?t.depends.map(id=>`<a href="#${E(D.tasks.find(x=>x.id===id).project)}" data-jump="${id}">${id}</a>`).join(', '):'no prerequisite'}${missing.length?' · '+missing.length+' still open':''}. Dependencies guide the sequence; they do not require proof uploads.</p><p class="muted">If blocked: keep the last working build, note the obstacle, and continue the next independent task. Cut optional scope before taking time from deployment and submission.</p>${r?.note?`<p class="note">${E(r.note)}</p>`:''}<button data-edit="${t.id}">Update progress</button></div></details>`;}
function matches(t){return(status==='all'||(status==='open'?stat(t)!=='done':stat(t)===status))&&JSON.stringify(t).toLowerCase().includes(search.toLowerCase())&&(windowFilter==='all'||(windowFilter==='contest'?!['follow-through','judging'].includes(t.phase):windowFilter==='later'?['follow-through','judging'].includes(t.phase):t.date>=M.dayKey()&&t.date<=new Date(Date.now()+7*86400000).toISOString().slice(0,10)));}
function toolbar(){return `<div class="filters"><label>Show<select id="status-filter">${['open','all','todo','doing','done','blocked','deferred'].map(s=>`<option ${s===status?'selected':''} value="${s}">${s==='open'?'All unfinished':s}</option>`).join('')}</select></label><label>Window<select id="window-filter">${[['all','Through completion'],['contest','Build & submission'],['later','Judging & follow-through'],['week','Next seven days']].map(([v,l])=>`<option value="${v}" ${v===windowFilter?'selected':''}>${l}</option>`).join('')}</select></label><label>Find a task<input id="search" type="search" value="${E(search)}" placeholder="Try deploy, vision, phone…"></label><button data-expand>Expand steps</button></div>`;}
function schedule(tasks){const ts=tasks.filter(matches).sort((a,b)=>a.date.localeCompare(b.date)||D.tasks.indexOf(a)-D.tasks.indexOf(b)),dates=[...new Set(ts.map(t=>t.date))];return toolbar()+(dates.length?dates.map(d=>{const day=ts.filter(t=>t.date===d),all=D.tasks.filter(t=>t.date===d&&stat(t)!=='done'),over=state.capacity!==null&&hours(all)>state.capacity;return `<section class="day"><h3>${dateLabel(d)}${d===M.dayKey()?' · TODAY':''}</h3><p class="${over?'error':'meta'}">${hours(day)}h shown · ${hours(all)}h unfinished across all lanes${state.capacity===null?' · capacity not set':` · ${state.capacity}h capacity${over?' · OVER CAPACITY: cut or move scope':''}`}</p>${day.map(task).join('')}</section>`;}).join(''):'<p>No tasks match. Change the filters to see the full plan.</p>');}
function overview(){return `<section><p class="eyebrow">Product → contest → finish</p><h2>Six lanes. One shared schedule.</h2><p>The plan favors a complete, distinctive experience over a longer feature list. ${D.tasks.length} tasks include build steps, submission and defined follow-through; they are not ${D.tasks.length} new features.</p><div class="notice"><b>Corrected Meta alignment:</b> Living Table: First Steps → recommended <b>Indie developer</b> track and <b>Build for Your World</b> theme. The later VR Start entry remains chess-focused Gaming. Actual accepted enrollment is separate from this strategic recommendation.</div><div class="grid project-grid">${D.projects.map(p=>{const ts=D.tasks.filter(t=>t.project===p.id),next=ts.find(t=>stat(t)!=='done');return `<article class="project-card"><p class="eyebrow">${E(p.contest)}</p><h3><a href="#${p.id}">${E(p.name)}</a></h3><p><b>${E(p.angle)}</b></p><p>${E(p.pitch)}</p><p class="meta">${E(p.status)}<br>Target: ${E(p.target)}</p><p>${done(ts)} / ${ts.length} tasks marked done</p><a class="button" href="#${p.id}">Full breakdown →</a>${next?`<p class="meta">Next: ${E(next.title)}</p>`:''}</article>`;}).join('')}</div></section><section class="section"><h2>Where to spend attention now</h2><ol><li><b>Frenemies, through Nov 2:</b> deploy the newer local build, finish the live show loop and record the Twitch payoff.</li><li><b>Living Table: First Steps, through Nov 4:</b> reuse the current base, add one useful Meta-model interaction and show it working.</li><li><b>Unity and MegaJam:</b> prepare tooling now; create the actual games after each permitted opening.</li><li><b>VR Start, through Nov 18:</b> keep improving the chess handoff. Shared LT tasks also support First Steps.</li><li><b>MAYHEM:</b> finish device and public-party acceptance; avoid expanding the 16-game catalog.</li></ol><div class="notice warning">Dates are proposed, not reserved time. The combined schedule can exceed one person’s capacity. If a day does not fit, protect the nearest submission, cut optional scope and retain later product tasks as unfinished—not silently done.</div><a class="button primary" href="#schedule">Open combined daily plan →</a></section>`;}
function detail(p){const ts=D.tasks.filter(t=>t.project===p.id);return `<section><p class="eyebrow">${E(p.contest)}</p><h2>${E(p.name)}</h2><p class="intro"><b>${E(p.angle)}</b> ${E(p.pitch)}</p><p><b>Alignment:</b> ${E(p.track)}</p><p><b>Target:</b> ${E(p.target)}${p.deadline?' · Hard close: '+new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Chicago'}).format(new Date(p.deadline))+' Central':''}</p><div class="two"><section><h3>Start from here</h3><ul>${p.facts.map(s=>`<li>${E(s)}</li>`).join('')}</ul><p class="meta">Snapshot reviewed Oct 29. Release records are context, not newly rerun tests.</p><p><a href="${E(p.url)}" target="_blank" rel="noopener">${p.id==='meta'||p.id==='unity'||p.id==='mega'?'Official event':'Open current product/dashboard'} ↗</a>${p.repo?` · <a href="${E(p.repo)}" target="_blank" rel="noopener">Source ↗</a>`:''}</p></section><section><h3>Three priorities</h3><ol>${p.priorities.map(s=>`<li>${E(s)}</li>`).join('')}</ol><h3>Build this</h3><p>${E(p.build)}</p><h3>Show judges this</h3><p>${E(p.demo)}</p></section></div><div class="notice warning"><b>Cut from this contest sprint:</b> ${E(p.cut)}</div><h3>Finish line</h3><p>${E(p.finish)}</p><details><summary>Remaining gaps and contest constraints</summary><ul>${p.gaps.map(s=>`<li>${E(s)}</li>`).join('')}</ul><p>${E(p.rules)}</p><a href="${E(p.source)}" target="_blank" rel="noopener">Official/source reference ↗</a></details><p>${done(ts)} / ${ts.length} tasks marked done · Dates below include submission, judging and bounded product follow-through.</p><button data-download="${p.id}">Download this runbook</button></section><section class="section"><h2>Daily task list</h2>${schedule(ts)}</section>`;}
function records(){return `<section><h2>Your progress, without an evidence audit</h2><p>Mark tasks done when you finish them. Notes are optional. Old dashboard records remain in <a href="legacy.html">the older dashboard</a>; no historical status is silently promoted into this plan.</p><div class="actions"><button id="export">Export progress</button><label class="button">Import progress<input id="import" type="file" accept="application/json,.json" hidden></label><button data-download="all">Download all runbooks</button></div><p>Import accepts this dashboard’s backup or the Living Table chess tracker export. Living Table observations map to matching LT- task IDs; this is an explicit progress transfer, not cross-site synchronization.</p><h3>Rule references</h3><ul>${D.sources.map(s=>`<li><a href="${E(s.url)}" target="_blank" rel="noopener">${E(s.name)}</a></li>`).join('')}</ul><p>Public rules were checked October 29. Meta participant terms, Unity’s full rules and MegaJam’s Box rules still need the entrant’s final review. Track recommendations are not changes to registered accounts.</p></section>`;}
function render(){const r=route(),p=project(r);$('project-nav').innerHTML=D.projects.map(p=>`<a class="button ${r===p.id?'primary':''}" href="#${p.id}">${E(p.name)}</a>`).join('');$('app').innerHTML=p?detail(p):r==='schedule'?`<section><h2>Daily execution across all projects</h2><p>Tasks are sequenced, not simultaneous. Living Table shared tasks appear once and are referenced by the First Steps lane.</p><label>Hours you can actually spend per day<input id="capacity" type="number" min="0" max="24" step="0.5" value="${state.capacity??''}" placeholder="Not set"></label><button id="capacity-save">Update capacity</button>${schedule(D.tasks)}</section>`:r==='records'?records():overview();bind();}
function bind(){if($('status-filter'))$('status-filter').onchange=e=>{status=e.target.value;render();};if($('window-filter'))$('window-filter').onchange=e=>{windowFilter=e.target.value;render();};if($('search'))$('search').onchange=e=>{search=e.target.value;render();};if($('capacity-save'))$('capacity-save').onclick=()=>{const raw=$('capacity').value,v=raw===''?null:Number(raw);if(v!==null&&(!Number.isFinite(v)||v<0||v>24)){$('notice').textContent='Enter 0–24 hours, or leave capacity blank.';return;}state.capacity=v;save();render();};if($('export'))$('export').onclick=()=>download('contest-command-progress.json',JSON.stringify(state,null,2));if($('import'))$('import').onchange=importFile;}
async function importFile(e){try{const file=e.target.files[0];if(!file)return;if(file.size>8000000)throw Error('File too large');const raw=JSON.parse(await file.text());let records;if(raw.schema===1&&raw.plan==='living-table-chess-2026'&&Array.isArray(raw.events)){records={};for(const v of raw.events){const id='LT-'+v.id;if(!D.tasks.some(t=>t.id===id))continue;if(!['pass','fail','blocked','doing','todo'].includes(v.status)||typeof v.note!=='string'||!Number.isFinite(Date.parse(v.at)))throw Error('Invalid Living Table observation');const r={status:v.status==='pass'?'done':v.status==='fail'?'blocked':v.status,note:`Imported LT observation (${v.hash||'unknown build'}): ${v.note}`,updated:v.at};records=M.merge(records,{[id]:r});}records=M.validate({schema:2,plan:'contest-command-rundowns',records,capacity:null},D.tasks).records;}else records=M.validate(raw,D.tasks).records;state.records=M.merge(state.records,records);save();render();$('notice').textContent='Progress merged; newer records retained.';}catch(err){$('notice').textContent='Import rejected: '+err.message;}finally{e.target.value='';}}
function runbook(id){const ps=id==='all'?D.projects:[project(id)];let s='# Contest Command — execution runbook\n\nOctober 29, 2026. Proposed dates; no evidence uploads required. No prize guarantee.\n';for(const p of ps){s+=`\n## ${p.name}\n\n${p.pitch}\n\nAlignment: ${p.track}\n\nBuild: ${p.build}\n\nDemo: ${p.demo}\n\nCut: ${p.cut}\n\nFinish: ${p.finish}\n`;for(const t of D.tasks.filter(t=>t.project===p.id).sort((a,b)=>a.date.localeCompare(b.date))){s+=`\n- [ ] **${t.date} · ${t.id}: ${t.title}** (${t.hours}h; ${t.owner})\n\n`;t.steps.forEach((x,i)=>s+=`  ${i+1}. ${x}\n`);s+=`\n  Done when: ${t.done}\n  Do first: ${t.depends.join(', ')||'none'}\n`;if(t.condition)s+=`  Note: ${t.condition}\n`;}}download('contest-command-'+id+'-runbook.md',s,'text/markdown');}
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit]'),expand=e.target.closest('[data-expand]'),dl=e.target.closest('[data-download]'),jump=e.target.closest('[data-jump]');if(expand)document.querySelectorAll('details.task').forEach(d=>d.open=true);if(dl)runbook(dl.dataset.download);if(jump){e.preventDefault();const t=D.tasks.find(t=>t.id===jump.dataset.jump);status='all';windowFilter='all';search='';history.replaceState(null,'','#'+t.project);render();const el=$('task-'+t.id);el.open=true;el.scrollIntoView({block:'center'});}if(edit){editing=D.tasks.find(t=>t.id===edit.dataset.edit);$('edit-title').textContent=editing.id+' · '+editing.title;$('edit-deps').textContent='Suggested prerequisites: '+(editing.depends.join(', ')||'none');$('result').value=stat(editing);$('note').value=state.records[editing.id]?.note||'';$('editor').showModal();}});
$('cancel').onclick=()=>$('editor').close();$('edit-form').onsubmit=e=>{e.preventDefault();state.records[editing.id]={status:$('result').value,note:$('note').value.trim(),updated:new Date().toISOString()};save();$('editor').close();render();};addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();
})();
